import {readFile,writeFile,mkdir,chmod} from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
export function configPath() {return process.env.CREW_CONFIG??path.join(os.homedir(),'.config','crew','config.json');}
export async function readConfig(file=configPath()) {
  try{return JSON.parse(await readFile(file,'utf8'));}catch(error){if(error.code==='ENOENT')return {};throw new Error('Cannot read Crew config: '+error.message);}
}
export async function saveConfig(config,file=configPath()) {
  await mkdir(path.dirname(file),{recursive:true,mode:0o700});
  await writeFile(file,JSON.stringify(config,null,2)+'\n',{mode:0o600});
  await chmod(file,0o600);
}
export class CrewClient {
  constructor({url='http://localhost:4100',token,cookie}={}) {this.url=url.replace(/\/$/,'');this.token=token;this.cookie=cookie;}
  async request(method,route,body,options={}) {
    const headers={'X-Crew-Request':'1',...options.headers};
    if(this.token)headers.Authorization='Bearer '+this.token;
    else if(this.cookie)headers.Cookie=this.cookie;
    const raw=body instanceof Uint8Array || options.stream;
    if(body!==undefined&&!raw)headers['Content-Type']='application/json';
    const response=await fetch(this.url+'/api/v1'+route,{method,headers,body:body===undefined?undefined:raw?body:JSON.stringify(body),signal:AbortSignal.timeout(15000),...(options.stream?{duplex:'half'}:{})});
    const cookie=response.headers.get('set-cookie');
    if(cookie)this.cookie=cookie.split(';')[0];
    if(options.response && response.ok)return response;
    if(options.binary){if(!response.ok)throw new Error('Download failed ('+response.status+')');return Buffer.from(await response.arrayBuffer());}
    const type=response.headers.get('content-type')??'';
    const data=type.includes('json')?await response.json():await response.text();
    if(!response.ok){const error=new Error(data.error?.message??'Request failed');error.code=data.error?.code;error.details=data.error?.details;error.status=response.status;throw error;}
    return data;
  }
  get(route,options){return this.request('GET',route,undefined,options);}
  post(route,body,options){return this.request('POST',route,body,options);}
  patch(route,body,options){return this.request('PATCH',route,body,options);}
  delete(route,body,options){return this.request('DELETE',route,body,options);}
}
export function query(values={}) {const search=new URLSearchParams(Object.entries(values).filter(([,v])=>v!==undefined&&v!==true));return search.size?'?'+search:'';}

import { createReadStream } from 'node:fs';
import { stat, open, rm } from 'node:fs/promises';
import path from 'node:path';
import { Readable, Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { createHash } from 'node:crypto';
export async function attachmentCommand(action, id, { options, client, print }) {
  if (!id) throw new Error('Provide an issue or attachment ID');
  if (action === 'attachments') return print(await client.get('/issues/' + encodeURIComponent(id) + '/attachments'));
  if (action === 'attach') {
    if (!options.file || options.file === true) throw new Error('Provide --file PATH');
    const file = await stat(options.file);
    if (!file.isFile()) throw new Error('Attachment source must be a regular file');
    const headers = { 'Content-Type': 'application/octet-stream', 'Content-Length': String(file.size) };
    if (options.sha256) headers['X-Content-SHA256'] = options.sha256;
    return print(await client.request('POST', '/issues/' + encodeURIComponent(id) + '/attachments?name=' + encodeURIComponent(options.name ?? path.basename(options.file)), createReadStream(options.file), { stream: true, headers }));
  }
  if (action === 'attachment-delete') {
    if (!options.yes) throw new Error('Attachment deletion requires --yes');
    return print(await client.delete('/attachments/' + encodeURIComponent(id)));
  }
  if (action === 'download') {
    if (!options.output || options.output === true) throw new Error('Provide --output PATH. Existing files are never replaced.');
    const { attachment } = await client.get('/attachments/' + encodeURIComponent(id));
    const response = await client.request('GET', '/attachments/' + encodeURIComponent(id) + '/download', undefined, { response: true });
    const file = await open(options.output, 'wx', 0o600);
    const hash = createHash('sha256'); let size = 0;
    const verifier = new Transform({ transform(chunk, encoding, callback) { hash.update(chunk); size += chunk.length; callback(null, chunk); } });
    try {
      await pipeline(Readable.fromWeb(response.body), verifier, file.createWriteStream());
      const digest = hash.digest('hex');
      if (digest !== attachment.sha256 || size !== attachment.size) throw new Error('Downloaded attachment failed size or SHA-256 verification');
      return print({ attachmentId: attachment.id, output: options.output, size, sha256: digest });
    } catch (error) {
      await file.close().catch(() => {}); await rm(options.output, { force: true }); throw error;
    }
  }
  throw new Error('Unknown attachment action');
}

