}
function ids(raw) {
  return String(raw).split(',').map(value => value.trim()).filter(Boolean);
}
export async function boardCommand({ args, options, client, print }) {
  const [action = 'show', id] = args;
  if (action === 'help') return print('crew board show PROJECT [--q TEXT] [--assignee ID]\ncrew board move ISSUE --status ID [--before ISSUE|--after ISSUE]\ncrew board bulk PROJECT --issues ID,ID [--status ID] [--assignee ID|none] [--labels ID,ID|none] [--add-labels ID,ID] [--remove-labels ID,ID]\ncrew board attachments ISSUE | attach ISSUE --file PATH [--name NAME] [--sha256 HEX]\ncrew board download ATTACHMENT --output PATH | attachment-delete ATTACHMENT --yes');
  if (['attachments', 'attach', 'download', 'attachment-delete'].includes(action)) return attachmentCommand(action, id, { options, client, print });
  if (!id) throw new Error('Usage: crew board show <project-id> | move <issue-id> --status ID | bulk <project-id> --issues ID,ID');
  if (action === 'show') return print(await client.get('/projects/' + encodeURIComponent(id) + '/board' + query({ q: options.q, assigneeId: options.assignee })));
  if (action === 'move') {
    const body = { statusId: value(options, 'status') };
    if (options.before) body.beforeId = options.before;
    if (options.after) body.afterId = options.after;
    return print(await client.post('/issues/' + encodeURIComponent(id) + '/move', body));
  }
  if (action === 'bulk') {
    const changes = {};
    if (options.status) changes.statusId = options.status;
    if (options.assignee !== undefined) changes.assigneeId = options.assignee === 'none' ? null : options.assignee;
    if (options.labels !== undefined) changes.labelIds = options.labels === 'none' ? [] : ids(options.labels);
    const body = { issueIds: ids(value(options, 'issues')), changes };
    if (options['add-labels']) body.addLabelIds = ids(options['add-labels']);
    if (options['remove-labels']) body.removeLabelIds = ids(options['remove-labels']);
    return print(await client.post('/projects/' + encodeURIComponent(id) + '/issues/bulk', body));
  }
  throw new Error('Unknown board action: ' + action);
}

import { query } from '../client.js';
export const sprintHelp = [
  'crew sprint list --project ID [--status planned|active|completed] [--limit N] [--cursor CURSOR]',
  'crew sprint create --project ID --name NAME --start YYYY-MM-DD --end YYYY-MM-DD [--goal TEXT]',
  'crew sprint show ID | scope ID | burndown ID',
  'crew sprint update ID [--name NAME] [--goal TEXT] [--start DATE] [--end DATE]',
  'crew sprint add ID --issues ISSUE,ISSUE | remove ID --issue ISSUE',
  'crew sprint start ID | complete ID [--carry-over NEXT_SPRINT] | delete ID --yes',
  'Only one sprint is active per project. Completed history is immutable. Carry-over targets a planned sprint.'
