  if (action === 'list') return print(await client.get('/projects/' + encodeURIComponent(required(options.project, 'project')) + '/sprints' + query({ status: options.status, limit: options.limit, cursor: options.cursor })));
  if (action === 'create') return print(await client.post('/projects/' + encodeURIComponent(required(options.project, 'project')) + '/sprints', {
    name: required(options.name, 'name'), goal: options.goal ?? '', startDate: required(options.start, 'start'), endDate: required(options.end, 'end')
  }));
  if (!id) throw new Error('Provide a sprint ID. ' + sprintHelp);
