  if (action === 'show' || action === 'scope') return print(await client.get(path + (options.history ? '?history=true' : '')));
  if (action === 'burndown') return print(await client.get(path + '/burndown'));
  if (action === 'update') {
    const body = {};
    for (const name of ['name', 'goal']) if (options[name] !== undefined) body[name] = options[name];
    if (options.start !== undefined) body.startDate = options.start;
    if (options.end !== undefined) body.endDate = options.end;
    return print(await client.patch(path, body));
  }
  if (action === 'start') return print(await client.post(path + '/start', {}));
  if (action === 'complete') return print(await client.post(path + '/complete', options['carry-over'] ? { carryOverSprintId: options['carry-over'] } : {}));
  if (action === 'add') return print(await client.post(path + '/issues', { issueIds: required(options.issues, 'issues').split(',').map(value => value.trim()).filter(Boolean) }));
  if (action === 'remove') return print(await client.delete(path + '/issues/' + encodeURIComponent(required(options.issue, 'issue'))));
  if (action === 'delete') {
    if (!options.yes) throw new Error('Sprint deletion requires --yes');
    return print(await client.delete(path));
  }
  throw new Error('Unknown sprint action: ' + action + '. Use crew sprint help');
}

import { projectCommand } from './project.js';
import { boardCommand } from './board.js';
