export const commands = { project: projectCommand, issue: issueCommand, board: boardCommand, sprint: sprintCommand };

import { rm, access } from 'node:fs/promises';
import { rmSync } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import { AppError } from '@crew/shared';
import { getIssue, validateIssueReferences } from './issues.js';
import { attachmentName, expectedHash, blobPath, receiveAttachment, attachmentStream } from './attachment-storage.js';
export function publicAttachment(row) {
  return { id: row.id, projectId: row.project_id, issueId: row.issue_id, name: row.name,
    mediaType: row.media_type, size: row.size, sha256: row.sha256, createdBy: row.created_by, createdAt: row.created_at,
    downloadUrl: '/api/v1/attachments/' + row.id + '/download' };
}
export function registerAttachments(ctx) {
  const { app, db, requireAuth, permissions, asyncRoute } = ctx;
  function issue(req, permission = 'project:read') {
    const value = getIssue(ctx, req.params.issueId);
    permissions.assertProject(req, value.projectId, permission);
    return value;
  }
  function attachment(req, permission = 'project:read') {
    const row = db.prepare('SELECT * FROM attachments WHERE id=?').get(req.params.attachmentId);
    if (!row) throw new AppError('NOT_FOUND', 'Attachment not found', 404);
    permissions.assertProject(req, row.project_id, permission);
    return row;
  }
  function emit(actorId, orgId, row, action) {
    const value = publicAttachment(row);
    ctx.bus.emit({ actorId, orgId, projectId: row.project_id, entityType: 'attachment', entityId: row.id,
      action, before: action === 'deleted' ? value : null, after: action === 'created' ? value : null, time: ctx.now() });
  }
  app.get('/api/v1/issues/:issueId/attachments', requireAuth, (req, res) => {
    const value = issue(req);
    const rows = db.prepare('SELECT * FROM attachments WHERE issue_id=? ORDER BY created_at,id').all(value.id);
    res.json({ ...ctx.paginate(rows.map(publicAttachment), req.query), maxUploadBytes: ctx.config.maxUploadBytes });
  });
  app.post('/api/v1/issues/:issueId/attachments', requireAuth, asyncRoute(async (req, res) => {
    const value = issue(req, 'attachment:write'); validateIssueReferences(ctx, value.projectId, {});
    const name = attachmentName(req.query.name ?? req.get('x-file-name'));
    const shaExpectation = expectedHash(req.get('x-content-sha256'));
    const mediaType = String(req.get('content-type') ?? 'application/octet-stream').slice(0, 255);
    if (mediaType.includes('application/json')) throw new AppError('VALIDATION', 'Send raw attachment bytes with application/octet-stream', 422, { contentType: 'JSON bodies are not attachment streams' });
    const id = ctx.id();
    const stored = await receiveAttachment(req, ctx.config, id, shaExpectation);
    let row;
    try {
      permissions.assertProject(req, value.projectId, 'attachment:write');
      validateIssueReferences(ctx, value.projectId, {});
      getIssue(ctx, value.id);
      const time = ctx.now();
      db.prepare('INSERT INTO attachments VALUES (?,?,?,?,?,?,?,?,?)').run(id, value.projectId, value.id, name, mediaType, stored.size, stored.sha256, req.user.id, time);
      row = db.prepare('SELECT * FROM attachments WHERE id=?').get(id);
    } catch (error) { await rm(stored.target, { force: true }); throw error; }
    emit(req.user.id, value.orgId, row, 'created');
    res.status(201).json({ attachment: publicAttachment(row) });
  }));
  app.get('/api/v1/attachments/:attachmentId', requireAuth, (req, res) => res.json({ attachment: publicAttachment(attachment(req)) }));
  app.get('/api/v1/attachments/:attachmentId/download', requireAuth, asyncRoute(async (req, res) => {
    const row = attachment(req);
    try { await access(blobPath(ctx.config, row.id)); }
    catch (error) { if (error.code === 'ENOENT') throw new AppError('NOT_FOUND', 'Attachment bytes are unavailable', 404); throw error; }
    res.set({ 'Content-Type': 'application/octet-stream', 'Content-Length': String(row.size),
      'Content-Disposition': "attachment; filename*=UTF-8''" + encodeURIComponent(row.name),
      'X-Content-SHA256': row.sha256, ETag: '"sha256-' + row.sha256 + '"', 'Cache-Control': 'private, no-store' });
    try { await pipeline(attachmentStream(ctx.config, row.id), res); }
    catch (error) {
      if (!(['ERR_STREAM_PREMATURE_CLOSE', 'ECONNRESET'].includes(error.code) && res.destroyed)) throw error;
    }
  }));
  app.delete('/api/v1/attachments/:attachmentId', requireAuth, asyncRoute(async (req, res) => {
    const row = attachment(req, 'attachment:write');
    const project = permissions.assertProject(req, row.project_id, 'attachment:write');
    validateIssueReferences(ctx, project.id, {});
    await rm(blobPath(ctx.config, row.id), { force: true });
    db.prepare('DELETE FROM attachments WHERE id=?').run(row.id);
    emit(req.user.id, project.org_id, row, 'deleted'); res.json({ ok: true });
  }));
  const unsubscribe = ctx.bus.subscribe(event => {
    if (event.action !== 'deleted' || !['issue', 'project'].includes(event.entityType)) return;
    const column = event.entityType === 'issue' ? 'issue_id' : 'project_id';
    const rows = db.prepare('SELECT * FROM attachments WHERE ' + column + '=?').all(event.entityId);
    for (const row of rows) {
      rmSync(blobPath(ctx.config, row.id), { force: true });
      db.prepare('DELETE FROM attachments WHERE id=?').run(row.id);
      emit(event.actorId, event.orgId, row, 'deleted');
    }
  });
  (ctx.cleanups ??= []).push(unsubscribe);
}

export function formatBytes(bytes) {
  if (!Number.isFinite(bytes) || bytes < 0) return 'Unknown size';
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KiB';
  return (bytes / (1024 * 1024)).toFixed(1) + ' MiB';
}
export function uploadProgress(loaded, total) {
  return total > 0 ? Math.min(100, Math.max(0, Math.round(100 * loaded / total))) : 0;
}
export function validateUpload(file, maxBytes) {
  if (!file) return 'Choose a file to upload';
  if (file.size > maxBytes) return 'File exceeds the ' + formatBytes(maxBytes) + ' upload limit';
  if (!file.name || /[\/\\\x00-\x1f\x7f]/.test(file.name)) return 'Use a plain file name without separators';
  return null;
}
export function uploadAttachment({ issueId, file, onProgress, signal, createRequest = () => new XMLHttpRequest() }) {
  return new Promise((resolve, reject) => {
    const request = createRequest();
    const abort = () => request.abort();
    function finish(fn, value) {
      signal?.removeEventListener('abort', abort);
      fn(value);
    }
    request.open('POST', '/api/v1/issues/' + encodeURIComponent(issueId) + '/attachments?name=' + encodeURIComponent(file.name));
    request.withCredentials = true;
    request.timeout = 60000;
    request.setRequestHeader('X-Crew-Request', '1');
    request.setRequestHeader('Content-Type', 'application/octet-stream');
    request.upload.onprogress = event => onProgress?.({ loaded: event.loaded, total: event.lengthComputable ? event.total : file.size });
    request.onload = () => {
      let result;
      try { result = JSON.parse(request.responseText); }
      catch { finish(reject, new Error('The server returned an invalid upload response')); return; }
      if (request.status >= 200 && request.status < 300) finish(resolve, result);
      else {
        const error = new Error(result.error?.message ?? 'Upload failed');
        error.status = request.status; error.code = result.error?.code; error.details = result.error?.details;
        finish(reject, error);
      }
    };
    request.onerror = () => finish(reject, new Error('Upload connection failed. Check the attachment list before sending again.'));
    request.ontimeout = () => finish(reject, new Error('Upload timed out. Check the attachment list before sending again.'));
    request.onabort = () => finish(reject, new Error('Upload cancelled'));
    if (signal?.aborted) { finish(reject, new Error('Upload cancelled')); return; }
    signal?.addEventListener('abort', abort, { once: true });
    request.send(file);
  });
}

import { h } from 'preact';
import { useEffect, useRef, useState } from 'preact/hooks';
import { Page, Field, Button, Notice, Empty, Loading, useLoad } from '../../components/ui.jsx';
import { formatBytes, uploadProgress, validateUpload, uploadAttachment } from './attachment-state.js';
export function AttachmentsPanel({ api, issueId }) {
  const attachments = useLoad(() => api.get('/issues/' + issueId + '/attachments?limit=200'), [issueId]);
  const access = useLoad(async () => {
    const { issue } = await api.get('/issues/' + issueId);
    const project = await api.get('/projects/' + issue.projectId);
    return { write: project.permissions.write && !project.project.archived };
  }, [issueId]);
  const [file, setFile] = useState(null), [error, setError] = useState(null);
  const [notice, setNotice] = useState(''), [busy, setBusy] = useState(false);
  const [progress, setProgress] = useState(null);
  const controller = useRef(null), input = useRef(null);
  useEffect(() => () => controller.current?.abort(), [issueId]);
  async function upload(event) {
    event.preventDefault();
    const problem = validateUpload(file, attachments.data?.maxUploadBytes ?? 0);
    if (problem) { setError(new Error(problem)); return; }
    setError(null); setNotice(''); setBusy(true); setProgress({ loaded: 0, total: file.size });
    controller.current = new AbortController();
    try {
      const result = await uploadAttachment({ issueId, file, onProgress: setProgress, signal: controller.current.signal });
      setNotice(result.attachment.name + ' uploaded: ' + formatBytes(result.attachment.size) + ', SHA-256 ' + result.attachment.sha256);
      setFile(null); if (input.current) input.current.value = ''; attachments.reload();
    } catch (error) { setError(error); attachments.reload(); }
    finally { setBusy(false); controller.current = null; }
  }
  async function remove(attachment) {
    if (!globalThis.confirm('Delete attachment ' + attachment.name + '?')) return;
    setError(null); setBusy(true); setNotice('');
    try { await api.delete('/attachments/' + attachment.id); setNotice('Attachment deleted'); attachments.reload(); }
    catch (error) { setError(error); }
    finally { setBusy(false); }
  }
  return <section className="panel attachments-panel"><h2>Attachments</h2>
    <Notice error={error ?? attachments.error ?? access.error} /><Notice>{notice}</Notice>
    {attachments.loading ? <Loading /> : !attachments.data?.items.length ? <Empty>No attachments yet.</Empty> : <ul className="attachments-list">
      {attachments.data.items.map(attachment => <li key={attachment.id}>
        <div><a href={attachment.downloadUrl} download={attachment.name}>{attachment.name}</a>
          <p>{formatBytes(attachment.size)} · {attachment.mediaType} · {new Date(attachment.createdAt).toLocaleString()}</p>
          <details><summary>SHA-256 integrity digest</summary><code className="digest">{attachment.sha256}</code></details>
        </div>
        {access.data?.write && <Button busy={busy} onClick={() => remove(attachment)}>Delete</Button>}
      </li>)}
    </ul>}
    {access.data?.write && <form onSubmit={upload}>
      <p>Maximum upload: {formatBytes(attachments.data?.maxUploadBytes ?? 0)}. Bytes are streamed, stored privately, and hashed by the server.</p>
      <Field label="Attachment file"><input type="file" ref={input} disabled={busy} onChange={event => setFile(event.currentTarget.files[0] ?? null)} /></Field>
      {file && <p>{file.name} · {formatBytes(file.size)}</p>}
      {progress && <div role="status"><progress max="100" value={uploadProgress(progress.loaded, progress.total)} aria-label="Attachment upload progress" /> {uploadProgress(progress.loaded, progress.total)}% · {formatBytes(progress.loaded)} sent</div>}
      <Button busy={busy} disabled={!file || attachments.loading} type="submit">Upload attachment</Button>
      {busy && <Button type="button" onClick={() => controller.current?.abort()}>Cancel upload</Button>}
    </form>}
  </section>;
}
export function IssueAttachmentsPage({ api, params }) {
