export function scopePreview(issues, selected) {
  const values = issues.filter(issue => selected.has(issue.id));
  return { issueIds: values.map(issue => issue.id), count: values.length, points: values.reduce((sum, issue) => sum + (issue.estimate ?? 0), 0) };
}
export function completionPreview(scope) {
  const completed = scope.filter(item => item.done);
  const unfinished = scope.filter(item => !item.done);
  return {
    completedCount: completed.length, unfinishedCount: unfinished.length,
    completedPoints: completed.reduce((sum, item) => sum + item.estimate, 0),
    unfinishedPoints: unfinished.reduce((sum, item) => sum + item.remaining, 0),
    unfinishedIssueIds: unfinished.map(item => item.issueId)
  };
}
export function chartPoints(days, field, width = 700, height = 220) {
  const maximum = Math.max(1, ...days.flatMap(day => [day.scope ?? 0, day.remaining ?? 0, day.idealRemaining ?? 0]));
  return days.flatMap((day, index) => day[field] == null ? [] : [{
    date: day.date, value: day[field],
    x: 35 + index * (width - 55) / Math.max(1, days.length - 1),
    y: 15 + (1 - day[field] / maximum) * (height - 45)
  }]);
}
export function chartPath(points) {
  return points.map((point, index) => (index ? 'L' : 'M') + point.x.toFixed(2) + ',' + point.y.toFixed(2)).join(' ');
}

import { h } from 'preact';
